import { Paddle, Environment } from '@paddle/paddle-node-sdk';

const paddle = new Paddle(process.env.PADDLE_API_KEY!, {
  environment: Environment.Sandbox,
});

// Create a transaction (checkout) for a subscription price
const transaction = await paddle.transactions.create({
  items: [
    {
      priceId: 'pri_01h1234abcde', // Your Paddle price ID
      quantity: 1,
    },
  ],
  customData: {
    userId: 'user_123',
    planName: 'pro',
  },
  checkoutSettings: {
    successUrl: 'https://yourapp.com/success',
  },
});

// Redirect user to checkout
const checkoutUrl = transaction.checkout?.url;
console.log('Checkout URL:', checkoutUrl);

import { Paddle, Environment } from '@paddle/paddle-node-sdk';
import type { Request, Response } from 'express';

const paddle = new Paddle(process.env.PADDLE_API_KEY!, {
  environment: Environment.Sandbox,
});

export async function handlePaddleWebhook(req: Request, res: Response) {
  const signature = req.headers['paddle-signature'] as string;
  const rawBody = req.body as string; // Must be raw string, not parsed JSON

  let event;
  try {
    event = paddle.webhooks.unmarshal(
      rawBody,
      process.env.PADDLE_WEBHOOK_SECRET!,
      signature
    );
  } catch (err) {
    console.error('Webhook signature verification failed:', err);
    return res.status(400).send('Invalid signature');
  }

  // Use event.eventId as idempotency key to avoid double-processing
  const eventId = event.eventId;

  switch (event.eventType) {
    case 'subscription.created': {
      const subscription = event.data;
      console.log('New subscription:', subscription.id, 'customer:', subscription.customerId);
      // Provision access for the customer
      await provisionSubscription(subscription.customerId, subscription.id);
      break;
    }
    case 'transaction.completed': {
      const transaction = event.data;
      console.log('Payment succeeded:', transaction.id, 'total:', transaction.details?.totals?.total);
      // Update payment records
      await recordPayment(transaction.id, transaction.customerId);
      break;
    }
    case 'subscription.canceled': {
      const subscription = event.data;
      console.log('Subscription canceled:', subscription.id);
      // Revoke access at period end
      await scheduleAccessRevocation(subscription.customerId, subscription.scheduledChange?.effectiveAt);
      break;
    }
    default:
      console.log('Unhandled event type:', event.eventType);
  }

  // Always return 200 immediately
  return res.status(200).json({ received: true, eventId });
}

